import { projectRunnerUi } from "./redaction.mjs";

// Retained evidence only. This record is never an input to the browser model.
// The screenshot and text are separate observations, with separate times.
export async function captureUiObservation(
  page,
  {
    screenshot,
    afterAction,
    redact,
    validate,
    signal,
    deadline,
    timeoutMs = 1500,
  },
) {
  const record = {
    schema: "loki.runner.ui-observation/1",
    screenshot,
    afterAction,
    startedAt: new Date().toISOString(),
  };
  let timeout;
  const stop = (code) => Object.assign(new Error(code), { code });
  try {
    if (signal?.aborted) throw stop("interrupted");
    const remaining = Math.min(timeoutMs, deadline - Date.now());
    if (remaining <= 0) throw stop("time_limit");
    validate();
    const url = page.url();
    timeout = AbortSignal.timeout(remaining);
    const snapshot = await page.locator("body").ariaSnapshot({
      timeout: remaining,
      signal: signal ? AbortSignal.any([signal, timeout]) : timeout,
    });
    validate();
    if (page.url() !== url) throw stop("page_changed");
    return {
      ...record,
      ...projectRunnerUi({ url, snapshot }, redact),
      finishedAt: new Date().toISOString(),
      status: "captured",
    };
  } catch (error) {
    // Do not copy arbitrary browser errors, which can include page content.
    return {
      ...record,
      finishedAt: new Date().toISOString(),
      status: "unavailable",
      reason: signal?.aborted
        ? "interrupted"
        : timeout?.aborted
          ? "capture_timeout"
          : [
                "interrupted",
                "time_limit",
                "capture_timeout",
                "page_changed",
              ].includes(error.code)
            ? error.code
            : error.name === "TimeoutError"
              ? "capture_timeout"
              : "capture_failed",
    };
  }
}
